// 3 chế độ: lịch 8h (lấy tiêu đề đầu tiên chưa viết), /tieude <tiêu đề> (viết ngay), /dstieude (liệt kê hàng chờ)
const rows = $input.all().map(i => i.json);
let call = null;
try { call = $('Khi được gọi').first().json; } catch (e) {}
const nextId = rows.reduce((m, r) => Math.max(m, Number(r['ID']) || 0), 0) + 1;
const chuaViet = (r) => !String(r['Nội dung'] || '').trim() && ['', 'chờ viết'].includes(String(r['Trạng thái'] || '').trim().toLowerCase());
const pending = rows.filter(r => String(r['Tiêu đề'] || '').trim() && chuaViet(r));
const oVangTrong = rows.filter(r => !String(r['Tiêu đề'] || '').trim() && chuaViet(r) && String(r['Trạng thái'] || '').trim() === 'Chờ viết');

if (call && call.route === 'dstieude') {
  const list = pending.slice(0, 20).map((r, i) => `${i + 1}. ${String(r['Tiêu đề']).trim()}`).join('\n');
  const oTxt = `🟨 Còn ${oVangTrong.length} ô vàng trống trên Sheet để gõ thêm tiêu đề.`;
  const reply = pending.length
    ? `📋 ${pending.length} TIÊU ĐỀ ĐANG CHỜ VIẾT (8h sáng bot viết dòng trên cùng):\n${list}${pending.length > 20 ? '\n…' : ''}\n\n${oTxt}\n✍️ Muốn viết ngay: gõ "/tieude <tiêu đề>"`
    : `📋 Chưa có tiêu đề nào chờ viết (các ô vàng trên Sheet đều đang trống).\n${oTxt}\n✍️ Gõ "/tieude <tiêu đề>" để bot viết ngay, hoặc gõ tiêu đề vào ô vàng để 8h sáng bot viết.`;
  return [{ json: { found: false, mode: 'ds', reply } }];
}
if (call && call.route === 'tieude') {
  const tieuDe = String(call.title || '').replace(/\s+/g, ' ').trim();
  if (tieuDe.length < 5) return [{ json: { found: false, mode: 'tieude', reply: 'ℹ️ Cách dùng: /tieude <tiêu đề bài>\nVí dụ: /tieude 5 phím tắt Google Sheets giúp bạn làm việc nhanh gấp đôi' } }];
  // Ghi vào ô vàng trống đầu tiên (Trạng thái "Chờ viết", chưa có tiêu đề); hết ô vàng thì ghi xuống dòng mới
  const maxRow = rows.reduce((m, r) => Math.max(m, Number(r.row_number) || 1), 1);
  return [{ json: { found: true, mode: 'tieude', tieuDe, row_number: oVangTrong.length ? oVangTrong[0].row_number : maxRow + 1, id: nextId, conLai: pending.length } }];
}
if (!pending.length) return [{ json: { found: false, mode: 'lich', conLai: 0 } }];
const r = pending[0];
return [{ json: { found: true, mode: 'lich', tieuDe: String(r['Tiêu đề']).trim(), row_number: r.row_number,
  id: Number(r['ID']) || nextId, conLai: pending.length - 1 } }];

// Giữ trong Sheet luôn có 10 ô vàng trống ("Chờ viết", chưa có tiêu đề) để người phụ trách gõ tiêu đề
const MUC_TIEU = 10;
const rows = $('Đọc lịch đăng').all().map(i => i.json);
const daDung = Number($('Chọn tiêu đề').first().json.row_number);
const trong = rows.filter(r => !String(r['Tiêu đề'] || '').trim() && !String(r['Nội dung'] || '').trim()
  && String(r['Trạng thái'] || '').trim() === 'Chờ viết' && Number(r.row_number) !== daDung).length;
const them = Math.max(0, MUC_TIEU - trong);
return Array.from({ length: them }, () => ({ json: { 'Trạng thái': 'Chờ viết' } }));
